const app=document.querySelector('#app');
const state={data:null,locale:localStorage.getItem('dracula.language')||'ro',cart:{items:[]},profile:null,favorites:[],filter:'all',search:'',auth:'login',order:null,checkoutKey:null};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=k=>esc(state.data?.ui[k]||k);
const money=n=>new Intl.NumberFormat(state.locale,{style:'currency',currency:state.data.currency}).format(Number(n)||0);
const href=path=>`/${state.locale}${path}`;
const link=(path,label,cls='')=>`<a class="${cls}" href="${href(path)}" data-link>${label}</a>`;
const icon=name=>`<svg class="sigil" viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="1.25" aria-hidden="true">${({bag:'<path d="M7 10h18l2 17H5L7 10ZM11 11V8a5 5 0 0 1 10 0v3M11 17l5 7 5-7M16 14v10"/>',favorite:'<path d="M16 3 27 13 16 29 5 13 16 3ZM5 13h22M11 8l5 16 5-16"/>',account:'<path d="M16 3 28 10v12l-12 7L4 22V10L16 3Z"/><circle cx="16" cy="12" r="4"/><path d="M9 24v-3a7 7 0 0 1 14 0v3"/>',buy:'<path d="M3 16h24M19 7l9 9-9 9M9 10l5 6-5 6"/>',close:'<path d="m8 8 16 16M24 8 8 24"/>'})[name]}</svg>`;
function route(){const parts=location.pathname.split('/').filter(Boolean);if(state.data?.languages.includes(parts[0]))parts.shift();return '/'+parts.join('/');}
async function api(path,method='GET',body,extra={}){const csrf=decodeURIComponent(document.cookie.split('; ').find(c=>c.startsWith('dracula_csrf='))?.split('=').slice(1).join('=')||'');const r=await fetch(path+(path.includes('?')?'&':'?')+'lang='+state.locale,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...extra},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(data.error||data.code||'general');e.status=r.status;throw e;}return data;}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
function errorMessage(e){return state.data?.ui['error.'+e.message]||state.data?.ui['error.general']||e.message;}
async function refresh(){const results=await Promise.allSettled([api('/api/cart'),api('/api/account/profile'),api('/api/account/favorites')]);if(results[0].status==='fulfilled')state.cart=results[0].value;state.profile=results[1].status==='fulfilled'?results[1].value.profile:null;state.favorites=results[2].status==='fulfilled'?results[2].value.items:[];}
function saved(p){return state.favorites.some(f=>f.product_id===p.id||f.id===p.external_id||f.id===p.id);}
function image(p,cls='',lazy=true){return `<img class="${cls}" src="${esc(p.image)}" alt="${esc(p.name)}" ${lazy?'loading="lazy"':''}>`;}
function favourite(p){return `<button class="icon-button ${saved(p)?'selected':''}" ${p.is_preview?'disabled':''} data-action="favorite" data-id="${p.id}" aria-pressed="${saved(p)}" aria-label="${t(saved(p)?'product.unfavorite':'product.favorite')}" title="${t('nav.favorites')}">${icon('favorite')}</button>`;}
function header(){return `<a class="skip-link" href="#main">${t('access.skip')}</a>${state.data.demo?`<div class="preview-label">${t('demo.label')}</div>`:''}<header class="header"><a href="${href('/')}" data-link class="logo"><img src="${esc(state.data.brand.logo_url)}" alt="${esc(state.data.brand.name)}"></a><nav aria-label="${t('access.navigation')}">${link('/collection',t('nav.collection'))}${link('/#signature',t('nav.story'))}${link('/#universe',t('nav.universe'))}</nav><div class="header-tools"><label class="language"><span class="sr-only">${t('nav.language')}</span><select id="language">${state.data.languages.map(l=>`<option ${l===state.locale?'selected':''} value="${l}">${l.toUpperCase()}</option>`).join('')}</select></label>${link('/account',icon('account')+`<span class="sr-only">${t('nav.account')}</span>`,'icon-button')}${link('/favorites',icon('favorite')+`<span class="sr-only">${t('nav.favorites')}</span>`,'icon-button')}${link('/bag',icon('bag')+`<span class="bag-count">${state.cart.items_count||0}</span><span class="sr-only">${t('nav.bag')}</span>`,'icon-button')}</div></header>`;}
function footer(){const group=(key,slugs)=>`<div><h3>${t(key)}</h3>${slugs.map(slug=>{const p=state.data.pages.find(p=>p.slug===slug);return p?link('/pages/'+slug,esc(p.title)):'';}).join('')}</div>`;return `<footer class="shop-footer"><div class="footer-brand"><img src="${esc(state.data.brand.logo_url)}" alt="${esc(state.data.brand.name)}"><p>${esc(state.data.legal.company_name)}<br>${esc(state.data.legal.address)}</p></div>${group('footer.client',['contact','shipping','payments','returns','withdrawal','faq'])}${group('footer.house',['about','legal-notice','accessibility'])}${group('footer.legal',['terms','privacy','cookies','data-deletion','complaints'])}<div class="footer-bottom"><span>© ${new Date().getFullYear()} ${esc(state.data.brand.name)}. ${t('footer.rights')}</span><a href="/admin/">${t('footer.admin')}</a></div></footer>`;}
function productPath(p){return (p.is_preview?'/preview/product/':'/product/')+p.external_id;}
function productPrice(p){return p.is_preview?t('product.preview'):money(p.price)+(state.data.demo?` <small>${t('demo.price')}</small>`:'');}
function bootstrapPath(){return '/api/dracula/bootstrap'+(location.pathname.split('/').includes('preview')?'?preview=1':'');}
function card(p,index=0){return `<article class="product ${index>2?'product-wide':''}"><div class="card-image">${link(productPath(p),image(p)+'<span class="view-label">'+t('product.discover')+' ↗</span>','product-image')}${favourite(p)}</div><div class="product-meta"><p>${esc(p.sku)}</p><h3>${link(productPath(p),esc(p.name))}</h3><div class="price-row"><span>${productPrice(p)}</span><button class="icon-button" data-action="add" data-id="${p.id}" ${p.is_preview||p.available<1?'disabled':''} aria-label="${t('product.add')}" title="${t('product.add')}">${icon('bag')}</button></div></div></article>`;}
function collection(){const products=state.data.products.filter(p=>(state.filter==='all'||p.category===state.filter||p.categories?.includes(state.filter))&&(`${p.name} ${p.description}`).toLowerCase().includes(state.search.toLowerCase()));return `${state.data.preview_available&&!state.data.preview_mode?link('/preview',t('collection.preview')+' ↗','text-link preview-link'):''}<div class="collection-tools"><div class="filters">${['all',...state.data.categories.map(c=>c.code)].map(f=>`<button class="${state.filter===f?'active':''}" data-action="filter" aria-pressed="${state.filter===f}" data-filter="${f}">${f==='all'?t('collection.all'):esc(state.data.categories.find(c=>c.code===f)?.name)}</button>`).join('')}</div><label class="search-label"><span class="sr-only">${t('collection.search')}</span><input id="search" type="search" value="${esc(state.search)}" placeholder="${t('collection.search')}"></label></div><div class="product-grid">${products.map(card).join('')||`<p>${t('collection.noresults')}</p>`}</div>`;}
function home(){const d=state.data;return `<section class="hero"><div class="hero-copy"><p class="eyebrow">${t('hero.eyebrow')}</p><h1>${t('hero.title')}<br><em>${t('hero.emphasis')}</em></h1><p class="hero-description">${t('hero.description')}</p>${link('/collection',t('hero.cta')+' <span>↗</span>','button-outline')}<p class="hero-motto">${t('hero.motto')}</p></div><div class="hero-photo"><img src="${esc(d.images.hero)}" alt="${t('hero.eyebrow')}" fetchpriority="high"></div><div class="hero-caption"><span>${t('hero.caption')}</span><a href="#collection">${t('hero.scroll')} ↓</a></div></section><section class="section" id="collection"><div class="section-heading"><div><p class="eyebrow">${t('collection.eyebrow')}</p><h2>${t('collection.title')}<br><em>${t('collection.emphasis')}</em></h2></div><p class="intro">${t('collection.description')}</p></div>${collection()}</section><section class="section signature" id="signature"><div class="signature-image"><img src="${esc(d.images.collection)}" loading="lazy" alt="${t('signature.title')}"></div><div class="signature-copy"><p class="eyebrow">${t('signature.eyebrow')}</p><h2>${t('signature.title')}<br><em>${t('signature.emphasis')}</em></h2><p class="intro">${t('signature.body')}</p><p class="intro">${t('signature.more')}</p>${link('/pages/about',t('nav.story')+' ↗','text-link')}</div></section><section class="section universe" id="universe"><div class="universe-copy"><p class="eyebrow">${t('universe.eyebrow')}</p><h2>${t('universe.title')}<br><em>${t('universe.emphasis')}</em></h2><p class="intro">${t('universe.body')}</p><p class="universe-manifesto">${t('universe.motto')}</p></div><div class="universe-photo"><img src="${esc(d.images.scarf)}" loading="lazy" alt="${t('universe.eyebrow')}"></div></section>`;}
function product(p){
 if(!p)return empty('error.not_found');
 const ready=!p.is_preview&&p.available>0;
 return `<section class="page product-detail"><div class="detail-photo"><button data-action="image" data-id="${p.id}" aria-label="${t('product.fullimage')}">${image(p,'',false)}</button></div><div class="detail-copy"><p class="eyebrow">${t('collection.eyebrow')}</p><h1>${esc(p.name)}</h1><p class="intro">${esc(p.description)}</p><div class="detail-price">${productPrice(p)}</div>${p.is_preview?`<p class="notice">${t('product.preview_note')}</p>`:`<p class="stock">${t(ready?'product.available':'product.unavailable')}</p><div class="purchase-row"><label>${t('product.quantity')}<input type="number" id="quantity" min="1" max="${p.available}" value="1"></label>${favourite(p)}</div><button class="button-primary" data-action="buy" data-id="${p.id}" ${ready?'':'disabled'}>${icon('buy')}${t('product.buy')}</button><button class="button-outline full" data-action="add" data-id="${p.id}" ${ready?'':'disabled'}>${icon('bag')}${t('product.add')}</button><p class="fineprint">${t('product.price_note')}</p>`}<p class="fineprint">${t('product.code')}: ${esc(p.sku)}</p><details><summary>${t('product.care')}</summary><p>${t('product.caretext')}</p></details><details><summary>${t('product.delivery')}</summary><p>${t('product.deliverytext')}</p>${link('/pages/returns',t('product.delivery'))}</details></div></section><section class="section product-dossier"><p class="eyebrow">${esc(p.sku)}</p><h2>${t('product.dossier')}</h2><div class="dossier-content">${rich(p.details)}</div></section><section class="section"><h2>${t('product.related')}</h2><div class="product-grid related">${state.data.products.filter(x=>x.id!==p.id).slice(0,3).map(card).join('')}</div></section>`;
}
function empty(key){return `<div class="empty"><span class="empty-sigil">${icon('favorite')}</span><h2>${t(key)}</h2>${link('/collection',t('action.continue'),'button-outline')}</div>`;}
function bagRows(edit=true){return state.cart.items.map(i=>`<article class="bag-row">${link('/product/'+i.id,`<img src="${esc(i.image)}" alt="${esc(i.name)}">`)}<div><h3>${link('/product/'+i.id,esc(i.name))}</h3><p>${money(i.unit_price_gross_ron)}</p>${edit?`<label>${t('product.quantity')} <input aria-label="${t('product.quantity')}" type="number" value="${i.qty}" min="1" max="${i.available}" data-qty="${i.product_id}"></label><button class="quiet" data-action="remove" data-id="${i.product_id}">${t('action.remove')}</button>`:`<span>× ${i.qty}</span>`}</div><strong>${money(i.line_total_gross_ron)}</strong></article>`).join('');}
function bag(){return `<section class="page"><p class="eyebrow">${t('nav.bag')}</p><h1>${t('bag.title')}</h1>${!state.cart.items.length?empty('bag.empty'):`<div class="checkout-grid"><div>${bagRows()}</div><aside class="order-summary"><h2>${t('bag.subtotal')}</h2><p class="total">${money(state.cart.products_gross_ron)}</p><p class="fineprint">${t('product.price_note')}</p>${state.data.demo?`<p class="notice">${t('checkout.demo_notice')}</p>`:''}${link('/checkout',t('bag.checkout')+' ↗','button-primary')}</aside></div>`}</section>`;}
function field(name,key,type='text',value='',required=true,extra=''){return `<label class="field">${t(key)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;}
function password(name,key){return field(name,key,'password','',true,'minlength="10" maxlength="200" autocomplete="new-password"');}
function formError(){return '<p class="form-error" role="alert"></p>';}
function auth(){const mode=state.auth;return `<section class="page auth-page"><div><p class="eyebrow">${t('hero.eyebrow')}</p><h1>${t('account.title')}</h1><p class="intro">${t('account.intro')}</p><span class="large-sigil">${icon('account')}</span></div><div class="form-panel"><div class="auth-tabs">${['login','register'].map(m=>`<button class="${m===mode?'active':''}" data-action="auth" data-mode="${m}">${t('auth.'+m)}</button>`).join('')}</div><form data-form="${mode}">${mode==='register'?field('full_name','auth.name')+field('phone','auth.phone','tel','',false):''}${field('email','auth.email','email','',true,'autocomplete="email"')}${mode!=='forgot'?field('password','auth.password','password','',true,`minlength="10" autocomplete="${mode==='login'?'current-password':'new-password'}"`):''}${mode==='register'?password('password_confirm','auth.confirm')+`<p class="fineprint">${t('auth.password_hint')}</p><label class="check"><input name="accept_terms" type="checkbox" required>${t('auth.terms')} ${link('/pages/terms',state.data.pages.find(p=>p.slug==='terms').title)}</label>`:''}${formError()}<button class="button-primary" type="submit">${t(mode==='forgot'?'auth.reset_action':'auth.'+mode+'_action')}</button></form>${mode==='login'?`<button class="quiet" data-action="auth" data-mode="forgot">${t('auth.forgot')}</button>`:''}<p class="fineprint">${link('/pages/privacy',t('auth.privacy'))}</p></div></section>`;}
async function account(){if(!state.profile)return auth();const p=state.profile;const orders=await api('/api/account/orders');return `<section class="page"><div class="page-heading"><div><p class="eyebrow">${t('account.title')}</p><h1>${esc(p.full_name||p.name||p.email)}</h1></div><button class="quiet" data-action="logout">${t('account.logout')}</button></div><div class="account-grid"><div><h2>${t('account.orders')}</h2>${orders.orders.length?orders.orders.map(o=>`<article class="order-card"><div><strong>${esc(o.order_number||o.id)}</strong><span>${t('status.'+o.status)}</span></div><p>${esc(o.created_at_display||o.created_at?.slice(0,10))}</p><p>${money(o.total_gross_ron||o.total_ron||o.total)}</p><button class="quiet" data-action="order" data-number="${esc(o.order_number||o.id)}">${t('action.view')}</button></article>`).join(''):`<p class="intro">${t('account.noorders')}</p>`}</div><div class="form-panel"><h2>${t('account.profile')}</h2><form data-form="profile">${field('full_name','auth.name','text',p.full_name||p.name)}${field('phone','auth.phone','tel',p.phone,false)}${formError()}<button class="button-outline">${t('action.save')}</button></form><h2>${t('account.password')}</h2><form data-form="password">${field('current_password','auth.currentpassword','password')}${password('new_password','auth.newpassword')}${password('password_confirm','auth.confirm')}${formError()}<button class="button-outline">${t('action.save')}</button></form></div></div></section>`;}
function checkout(){if(!state.profile)return auth();if(!state.cart.items.length)return bag();state.checkoutKey??=crypto.randomUUID();const name=(state.profile.full_name||state.profile.name||'').split(' ');return `<section class="page"><p class="eyebrow">${t('checkout.subtitle')}</p><h1>${t('checkout.title')}</h1>${state.data.demo?`<p class="notice">${t('checkout.demo_notice')}</p>`:''}<form data-form="checkout" class="checkout-grid"><div class="form-panel"><h2>${t('checkout.contact')}</h2><div class="field-grid">${field('first_name','checkout.first_name','text',name.shift())}${field('last_name','checkout.last_name','text',name.join(' '))}${field('email','auth.email','email',state.profile.email)}${field('phone','auth.phone','tel',state.profile.phone)}</div><h2>${t('checkout.address')}</h2>${field('line1','checkout.line1')}${field('line2','checkout.line2','text','',false)}<div class="field-grid">${field('city','checkout.city')}${field('county','checkout.county')}${field('postal_code','checkout.postal')}<label class="field">${t('checkout.country')}<select name="country" id="country">${state.data.countries.map(c=>`<option value="${c}">${new Intl.DisplayNames([state.locale],{type:'region'}).of(c)}</option>`).join('')}</select></label></div><p class="fineprint">${t('checkout.billing_same')}</p><h2>${t('checkout.delivery')}</h2><select name="delivery_method" id="delivery" aria-label="${t('checkout.delivery')}"></select><h2>${t('checkout.payment')}</h2><select name="payment_method" id="payment" aria-label="${t('checkout.payment')}">${state.data.payments.map(p=>`<option value="${p.code}">${t(p.label_key)}</option>`).join('')}</select><label class="field">${t('checkout.notes')}<textarea name="notes" maxlength="2000"></textarea></label></div><aside class="order-summary"><h2>${t('checkout.review')}</h2>${bagRows(false)}<div class="totals"><p>${t('bag.subtotal')}<span>${money(state.cart.products_gross_ron)}</span></p><p>${t('bag.shipping')}<span id="shipping-total"></span></p><p class="total">${t('bag.total')}<span id="checkout-total"></span></p></div><label class="check"><input name="accept_terms" type="checkbox" required><span>${t('auth.terms')} ${link('/pages/terms',state.data.pages.find(p=>p.slug==='terms').title)}</span></label>${formError()}<button class="button-primary" type="submit">${icon('buy')}${t(state.data.demo?'checkout.place_demo':'checkout.place')}</button></aside></form></section>`;}
async function updateShipping(){const country=document.querySelector('#country');if(!country)return;state.shippingOptions=await api('/api/checkout/options?country='+country.value);const select=document.querySelector('#delivery');const prev=select.value;select.innerHTML=state.shippingOptions.delivery_methods.map(m=>`<option value="${m.code}" ${m.code===prev?'selected':''}>${t(m.label_key)}</option>`).join('');const method=state.shippingOptions.delivery_methods.find(m=>m.code===select.value);state.shipping=(method.free_over_ron!=null&&state.cart.products_gross_ron>=method.free_over_ron)?0:method.price_ron;document.querySelector('#shipping-total').textContent=money(state.shipping);document.querySelector('#checkout-total').textContent=money(state.cart.products_gross_ron+state.shipping);}
function confirmation(){const o=state.order;return `<section class="page confirmation">${icon('favorite')}<p class="eyebrow">${t(o?.demo?'demo.order':'checkout.received')}</p><h1>${t('checkout.confirmed')}</h1><p>${t('checkout.reference')}: <strong>${esc(o?.order_number||'')}</strong></p><p class="intro">${t(o?.demo?'checkout.test_saved':'checkout.received')}</p>${link('/account',t('account.orders'),'button-outline')}</section>`;}

function rich(value){
 if(!/<\/?[a-z][^>]*>/i.test(value||''))return esc(value).split(/\n\n/).map(v=>'<p>'+v.replace(/\n/g,'<br>')+'</p>').join('');
 const doc=new DOMParser().parseFromString(value,'text/html');
 const tags=new Set(['P','BR','STRONG','EM','B','I','UL','OL','LI','H2','H3','H4','BLOCKQUOTE','A','SECTION','TABLE','THEAD','TBODY','TR','TH','TD','CAPTION']);
 function clean(node){if(node.nodeType===3)return esc(node.textContent);if(node.nodeType!==1)return '';if(['SCRIPT','STYLE','IFRAME','OBJECT'].includes(node.tagName))return '';const body=[...node.childNodes].map(clean).join('');if(!tags.has(node.tagName))return body;const tag=node.tagName.toLowerCase();let attr='';if(tag==='a'){const target=node.getAttribute('href')||'';if(/^(https?:\/\/|mailto:|\/(?!\/))/.test(target))attr=' href="'+esc(target)+'" rel="noopener noreferrer"';}return '<'+tag+attr+'>'+body+(tag==='br'?'':'</'+tag+'>');}
 return [...doc.body.childNodes].map(clean).join('');
}

function legal(slug){const p=state.data.pages.find(p=>p.slug===slug);if(!p)return empty('error.not_found');const kind=({'contact':'contact','complaints':'complaint','withdrawal':'withdrawal','data-deletion':'privacy'})[slug];return `<section class="page legal-page"><p class="eyebrow">${esc(state.data.legal.company_name)}</p><h1>${esc(p.title)}</h1>${state.data.demo?`<p class="notice">${t('legal.draft')}</p>`:''}<div class="legal-body">${rich(p.body)}</div>${kind?`<form class="form-panel" data-form="inquiry" data-kind="${kind}"><h2>${t('contact.title')}</h2>${field('name','auth.name','text',state.profile?.full_name)}${field('email','auth.email','email',state.profile?.email)}<label class="field">${t('contact.message')}<textarea name="body" minlength="10" maxlength="5000" required></textarea></label><input class="honeypot" name="website" tabindex="-1" autocomplete="off" aria-hidden="true">${formError()}<button class="button-primary">${t('action.send')}</button></form>`:''}</section>`;}
function cookies(){return localStorage.getItem('dracula.cookies')?'':`<aside class="cookie-note"><div><strong>${t('cookie.title')}</strong><p>${t('cookie.body')} ${link('/pages/cookies',t('cookie.more'))}</p></div><button class="button-outline" data-action="cookies">${t('cookie.accept')}</button></aside>`;}

async function paymentReturn(path){
 if(!state.profile)return auth();
 const number=decodeURIComponent(path.split('/').pop());
 const result=await api('/api/account/orders/'+encodeURIComponent(number));const o=result.order||result;
 const pending=o.status==='pending_payment';
 return '<section class="page confirmation">'+icon('favorite')+'<h1>'+t(pending?'checkout.pending':'checkout.received')+'</h1><p>'+esc(number)+'</p><p>'+t('status.'+o.status)+'</p><p>'+money(o.total_ron||o.total)+'</p>'+(pending?'<button class="button-primary" data-action="pay" data-number="'+esc(number)+'">'+t('payment.card')+'</button>':'')+'<p>'+link('/account',t('account.orders'),'button-outline')+'</p></section>';
}

async function render(){let body;const path=route();if(path==='/')body=home();else if(path==='/collection'||path==='/preview')body=`<section class="page"><p class="eyebrow">${t('collection.eyebrow')}</p><h1>${t('collection.title')} <em>${t('collection.emphasis')}</em></h1>${state.data.preview_mode?`<p class="notice">${t('collection.preview_intro')}</p>`:''}${collection()}</section>`;else if(path.startsWith('/product/')||path.startsWith('/preview/product/'))body=product(state.data.products.find(p=>p.external_id===path.split('/').pop()));else if(path==='/bag')body=bag();else if(path==='/favorites')body=`<section class="page"><h1>${t('favorites.title')}</h1>${state.favorites.length?`<div class="product-grid">${state.data.products.filter(saved).map(card).join('')}</div>`:empty('favorites.empty')}</section>`;else if(path==='/account')body=await account();else if(path==='/checkout')body=checkout();else if(path==='/confirmation')body=confirmation();else if(path.startsWith('/checkout/confirmare/')||path.startsWith('/checkout/plata/'))body=await paymentReturn(path);else if(path.startsWith('/pages/'))body=legal(path.split('/')[2]);else if(path==='/reset-password')body=`<section class="page narrow"><h1>${t('auth.reset_title')}</h1><form data-form="reset">${password('password','auth.newpassword')}${password('password_confirm','auth.confirm')}${formError()}<button class="button-primary">${t('action.save')}</button></form></section>`;else body=empty('error.not_found');app.innerHTML=header()+`<main id="main" tabindex="-1">${body}</main>`+footer()+cookies();app.setAttribute('aria-busy','false');document.documentElement.lang=state.locale;document.title=(document.querySelector('h1')?.textContent||state.data.brand.name)+' — '+state.data.brand.name;await updateShipping();if(location.hash)requestAnimationFrame(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView());}
async function syncLocation(){const segment=location.pathname.split('/')[1];const locale=state.data.languages.includes(segment)?segment:state.locale;if(locale!==state.locale||Boolean(state.data.preview_mode)!==location.pathname.split('/').includes('preview')){state.locale=locale;state.data=await api(bootstrapPath());state.locale=state.data.locale;state.filter='all';await refresh();}await render();}
async function navigate(path){history.pushState({},'',path);await syncLocation();if(!location.hash)window.scrollTo({top:0,behavior:'instant'});document.querySelector('#main')?.focus({preventScroll:true});}
document.addEventListener('click',async e=>{const a=e.target.closest('a[data-link]');if(a&&!e.ctrlKey&&!e.metaKey){e.preventDefault();navigate(a.href).catch(err=>toast(errorMessage(err)));return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{if(action==='pay'){b.disabled=true;const payment=await api('/api/payments/stripe/session','POST',{order_number:b.dataset.number});location.assign(payment.url);}else if(action==='filter'){state.filter=b.dataset.filter;await render();}else if(action==='auth'){state.auth=b.dataset.mode;await render();}else if(action==='cookies'){localStorage.setItem('dracula.cookies','necessary');b.closest('.cookie-note').remove();}else if(action==='image'){const p=state.data.products.find(p=>p.id===b.dataset.id);const d=document.querySelector('#image-dialog');d.querySelector('img').src=p.image;d.querySelector('img').alt=p.name;d.setAttribute('aria-label',p.name);d.querySelector('button').ariaLabel=state.data.ui['action.close'];d.showModal();}else if(action==='close-image')document.querySelector('#image-dialog').close();else if(action==='add'||action==='buy'){b.disabled=true;await api('/api/cart/items','POST',{product_id:b.dataset.id,qty:Number(document.querySelector('#quantity')?.value||1)});state.checkoutKey=null;await refresh();if(action==='buy')await navigate(href('/checkout'));else{await render();toast(state.data.ui['bag.added']);}}else if(action==='favorite'){if(!state.profile){toast(state.data.ui['auth.required']);return await navigate(href('/account'));}const p=state.data.products.find(p=>p.id===b.dataset.id);const exists=saved(p);await api('/api/account/favorites'+(exists?'/'+p.id:''),exists?'DELETE':'POST',exists?undefined:{product_id:p.id});await refresh();await render();toast(state.data.ui[exists?'favorites.removed':'favorites.saved']);}else if(action==='remove'){await api('/api/cart/items/'+b.dataset.id,'DELETE');state.checkoutKey=null;await refresh();await render();}else if(action==='logout'){await api('/api/account/logout','POST',{});await refresh();await render();}else if(action==='order'){const result=await api('/api/account/orders/'+encodeURIComponent(b.dataset.number));const o=result.order||result;const lines=o.items||o.lines||[];const d=document.querySelector('#image-dialog');d.setAttribute('aria-label',b.dataset.number);d.querySelector('button').ariaLabel=state.data.ui['action.close'];d.querySelector('img').hidden=true;d.querySelector('.order-info')?.remove();d.insertAdjacentHTML('beforeend',`<div class="order-info"><h2>${esc(b.dataset.number)}</h2>${lines.map(l=>`<p>${esc(l.name||l.product_name||l.sku)} × ${l.qty} — ${money(l.line_total_gross_ron||l.total_ron)}</p>`).join('')}<p>${t('order.status')}: ${t('status.'+o.status)}</p></div>`);d.showModal();}}catch(err){toast(errorMessage(err));}finally{if(b.isConnected)b.disabled=false;}});
document.addEventListener('change',async e=>{try{if(e.target.id==='language'){const path=route();state.locale=e.target.value;localStorage.setItem('dracula.language',state.locale);state.data=await api(bootstrapPath());await refresh();await navigate(href(path)+location.hash);}if(e.target.matches('[data-qty]')){await api('/api/cart/items/'+e.target.dataset.qty,'PATCH',{qty:Number(e.target.value)});state.checkoutKey=null;await refresh();await render();}if(e.target.id==='country'||e.target.id==='delivery')await updateShipping();}catch(err){toast(errorMessage(err));}});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;const pos=e.target.selectionStart;render().then(()=>{const input=document.querySelector('#search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}});}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const f=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type="submit"],button');const err=form.querySelector('.form-error');err.textContent='';button.disabled=true;try{const type=form.dataset.form;if(['register','reset'].includes(type)&&f.password!==f.password_confirm)throw new Error('password_mismatch');if(type==='login'||type==='register'){await api('/api/account/'+type,'POST',{...f,accept_terms:!!f.accept_terms});await refresh();await render();}else if(type==='forgot'){await api('/api/account/forgot-password','POST',{email:f.email});toast(state.data.ui['auth.reset_sent']);}else if(type==='reset'){await api('/api/account/reset-password','POST',{...f,token:new URLSearchParams(location.search).get('token')});await navigate(href('/account'));}else if(type==='profile'){await api('/api/account/profile','PATCH',f);await refresh();toast(state.data.ui['account.saved']);}else if(type==='password'){if(f.new_password!==f.password_confirm)throw new Error('password_mismatch');await api('/api/account/change-password','POST',f);form.reset();toast(state.data.ui['account.saved']);}else if(type==='inquiry'){await api('/api/dracula/inquiry','POST',{...f,kind:form.dataset.kind});form.reset();toast(state.data.ui['contact.saved']);}else if(type==='checkout'){const payload={customer:{first_name:f.first_name,last_name:f.last_name,email:f.email,phone:f.phone},shipping_address:{line1:f.line1,line2:f.line2,city:f.city,county:f.county,postal_code:f.postal_code,country:f.country},delivery_method:f.delivery_method,payment_method:f.payment_method,notes:f.notes,accept_terms:!!f.accept_terms,expected_total_ron:Math.round((state.cart.products_gross_ron+state.shipping)*100)/100};const result=await api('/api/orders','POST',payload,{'Idempotency-Key':state.checkoutKey});state.order=result;state.checkoutKey=null;if(result.awaiting_payment){const payment=await api('/api/payments/stripe/session','POST',{order_number:result.order_number});location.assign(payment.url||payment.checkout_url);return;}await refresh();await navigate(href('/confirmation'));}}catch(error){err.textContent=errorMessage(error);}finally{button.disabled=false;}});
document.querySelector('#image-dialog').addEventListener('close',e=>{e.target.querySelector('img').hidden=false;e.target.querySelector('.order-info')?.remove();});
window.addEventListener('popstate',()=>syncLocation().catch(e=>toast(errorMessage(e))));
async function start(){try{const verificationUrl=new URL(location.href);const verificationToken=verificationUrl.pathname.endsWith('/account')?verificationUrl.searchParams.get('verify'):null;if(verificationToken){verificationUrl.searchParams.delete('verify');history.replaceState({},'',verificationUrl.pathname+verificationUrl.search+verificationUrl.hash);}const segment=location.pathname.split('/')[1];if(/^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$/.test(segment))state.locale=segment;state.data=await api(bootstrapPath());state.locale=state.data.locale;await refresh();await render();if(verificationToken){try{await api('/api/account/verify-email','POST',{token:verificationToken});await refresh();await render();toast(state.data.ui['auth.verified']);}catch(error){toast(errorMessage(error));}}}catch(e){app.innerHTML='<div class="empty"><h1>Dracula Design Office</h1><p role="alert">'+esc(e.message)+'</p><button onclick="location.reload()">↻</button></div>';}}
start();
